<template><main class="adm-tournaments"><header><div><p>Conteúdo</p><h1><Icon name="ph:trophy-bold"/> Torneios</h1></div><button class="adm-primary" @click="newTournament">Novo torneio</button></header><div class="layout"><section class="list"><button v-for="item in tournaments" :key="item._id" @click="edit(item)" :class="{selected:form._id===item._id}"><span><b>{{item.title}}</b><small>{{item.status==='published'?'Publicado':'Rascunho'}}</small></span><i :class="{active:item.active}"/></button><p v-if="!tournaments.length">Nenhum torneio criado.</p></section><form @submit.prevent="save"><label>Título<input v-model="form.title" maxlength="120" required></label><label>Descrição<textarea v-model="form.description" rows="4" maxlength="1000" required/></label><div class="cols"><label>Início<input v-model="form.startsAt" type="datetime-local" required></label><label>Fim<input v-model="form.endsAt" type="datetime-local" required></label></div><div class="cols"><label>Status<select v-model="form.status"><option value="draft">Rascunho</option><option value="published">Publicado</option></select></label><label class="check"><input v-model="form.active" type="checkbox"> Torneio ativo</label></div><label>Premiações (uma por linha)<textarea v-model="prizesText" rows="4"/></label><label>Regras (uma por linha)<textarea v-model="rulesText" rows="5"/></label><label>Ranking mock (Nome | pontos)<textarea v-model="rankingText" rows="6" placeholder="Ana M. | 9850"/></label><p v-if="message" :class="messageType">{{message}}</p><button class="adm-primary" :disabled="saving">{{saving?'Salvando...':'Salvar e publicar'}}</button></form></div></main></template>
<script setup lang="ts">definePageMeta({middleware:'admin',layout:'admin'});const{adminFetch,needsLogin}=useAdmin();const tournaments=ref<any[]>([]),saving=ref(false),message=ref(''),messageType=ref('ok');const empty=()=>({_id:'',title:'',description:'',startsAt:'',endsAt:'',status:'draft',active:false,prizes:[],rules:[],ranking:[]});const form=reactive<any>(empty()),prizesText=ref(''),rulesText=ref(''),rankingText=ref('');const dateInput=(v:any)=>v?new Date(v).toISOString().slice(0,16):'';const edit=(v:any)=>{Object.assign(form,v,{_id:String(v._id),startsAt:dateInput(v.startsAt),endsAt:dateInput(v.endsAt)});prizesText.value=(v.prizes||[]).join('\n');rulesText.value=(v.rules||[]).join('\n');rankingText.value=(v.ranking||[]).map((r:any)=>`${r.name} | ${r.score}`).join('\n')};const newTournament=()=>{Object.assign(form,empty());prizesText.value='';rulesText.value='';rankingText.value=''};const load=async()=>{const r=await adminFetch<any>('/api/admin/tournaments');tournaments.value=r.tournaments};const save=async()=>{saving.value=true;try{const ranking=rankingText.value.split('\n').filter(Boolean).map(line=>{const[name,score]=line.split('|');return{name:name?.trim(),score:Number(score)}});await adminFetch('/api/admin/tournaments',{method:'POST',body:{...form,prizes:prizesText.value.split('\n').filter(Boolean),rules:rulesText.value.split('\n').filter(Boolean),ranking}});message.value='Torneio salvo com sucesso.';messageType.value='ok';await load()}catch(e:any){message.value=e?.data?.message||'Erro ao salvar.';messageType.value='error'}finally{saving.value=false}};watch(needsLogin,v=>{if(!v)load()},{immediate:true})</script>
<style scoped>.adm-tournaments{max-width:1100px;margin:auto;color:var(--adm-text)}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}header p{color:var(--adm-accent);font-size:11px;text-transform:uppercase;font-weight:900}h1{display:flex;gap:10px;align-items:center}.layout{display:grid;grid-template-columns:300px 1fr;gap:18px}.list,form{padding:18px;border:1px solid var(--adm-border);border-radius:16px;background:var(--adm-panel)}.list button{display:flex;justify-content:space-between;width:100%;padding:14px;border:1px solid transparent;border-radius:10px;background:none;color:var(--adm-text);text-align:left;cursor:pointer}.list button.selected{border-color:var(--adm-accent);background:var(--adm-accent-soft)}.list span{display:grid;gap:4px}.list small{color:var(--adm-muted)}.list i{width:9px;height:9px;border-radius:50%;background:var(--adm-border)}.list i.active{background:var(--adm-green)}form{display:grid;gap:16px}label{display:grid;gap:7px;color:var(--adm-muted);font-size:12px;font-weight:700}input,textarea,select{padding:12px;border:1px solid var(--adm-border);border-radius:9px;background:var(--adm-input);color:var(--adm-text);font:inherit}.cols{display:grid;grid-template-columns:1fr 1fr;gap:12px}.check{display:flex;align-items:center}.check input{width:auto}.adm-primary{padding:12px 17px;border:0;border-radius:10px;background:var(--adm-accent);color:#fff;font-weight:800;cursor:pointer}.ok{color:var(--adm-green)}.error{color:var(--adm-red)}@media(max-width:750px){.layout{grid-template-columns:1fr}.cols{grid-template-columns:1fr}}</style>
